import{_ as p,a0 as l,w as o,s as r,ao as h,I as n,x as i,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Git 系列（四）：在 Git 中进行版本回退 | LCTT x X-CMD","titleTemplate":false,"description":"Git 系列（四）：在 Git 中进行版本回退 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 系列（四）：在 Git 中进行版本回退 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 系列（四）：在 Git 中进行版本回退 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160726 How to restore older file versions in Git","title":"Git 系列（四）：在 Git 中进行版本回退","tag":"201608","desc":""},"relativePath":"201608/20160726 How to restore older file versions in Git.md","filePath":"[post].md"}'),g={name:"201608/20160726 How to restore older file versions in Git.md"};function d(c,s,k,b,u,f){const a=l("Link");return o(),r("div",null,[s[13]||(s[13]=h(`<h1 id="git-系列-四-在-git-中进行版本回退" tabindex="-1">Git 系列（四）：在 Git 中进行版本回退 <a class="header-anchor" href="#git-系列-四-在-git-中进行版本回退" aria-label="Permalink to “Git 系列（四）：在 Git 中进行版本回退”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/file_system.jpg?itok=s2b60oIB" alt=""></p><p>在这篇文章中，你将学到如何查看项目中的历史版本，如何进行版本回退，以及如何创建 Git 分支以便你可以大胆尝试而不会出现问题。</p><p>在你的 Git 项目的历史中，你的位置就像是摇滚专辑中的一个片段，由一个被称为 HEAD 的 标记来确定（如磁带录音机或录音播放器的播放头）。要在你的 Git 时间线上前后移动 HEAD ，需要使用 <code>git checkout</code> 命令。</p><p>git checkout 命令的使用方式有两种。最常见的用途是从一个以前的提交中恢复文件，你也可以整个倒回磁带，切换到另一个分支。</p><h3 id="恢复一个文件" tabindex="-1">恢复一个文件 <a class="header-anchor" href="#恢复一个文件" aria-label="Permalink to “恢复一个文件”">​</a></h3><p>当你意识到一个本来很好文件被你完全改乱了。我们都这么干过：我们把文件放到一个地方，添加并提交，然后我们发现它还需要做点最后的调整，最后这个文件被搞得面目全非了。</p><p>要把它恢复到最后的完好状态，使用 git checkout 从最后的提交（即 HEAD）中恢复：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout HEAD filename</span></span></code></pre></div><p>如果你碰巧提交了一个错误的版本，你需要找回更早的版本，使用 git log 查看你更早的提交，然后从合适的提交中找回它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>79a4e5f bad take</span></span>
<span class="line"><span>f449007 The second commit</span></span>
<span class="line"><span>55df4c2 My great project, first commit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git checkout 55df4c2 filename</span></span></code></pre></div><p>现在，以前的文件恢复到了你当前的位置。（任何时候你都可以用 git status 命令查看你的当前状态）因为这个文件改变了，你需要添加这个文件，再进行提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add filename</span></span>
<span class="line"><span>$ git commit -m &#39;restoring filename from first commit.&#39;</span></span></code></pre></div><p>使用 Git log 验证你所提交的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>d512580 restoring filename from first commit</span></span>
<span class="line"><span>79a4e5f bad take</span></span>
<span class="line"><span>f449007 The second commit</span></span>
<span class="line"><span>55df4c2 My great project, first commit.</span></span></code></pre></div><p>从本质上讲，你已经倒好了磁带并修复了坏的地方，所以你需要重新录制正确的。</p><h3 id="回退时间线" tabindex="-1">回退时间线 <a class="header-anchor" href="#回退时间线" aria-label="Permalink to “回退时间线”">​</a></h3><p>恢复文件的另一种方式是回退整个 Git 项目。这里使用了分支的思想，这是另一种替代方法。</p><p>如果你要回到历史提交，你要将 Git HEAD 回退到以前的版本才行。这个例子将回到最初的提交处：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>d512580 restoring filename from first commit</span></span>
<span class="line"><span>79a4e5f bad take</span></span>
<span class="line"><span>f449007 The second commit</span></span>
<span class="line"><span>55df4c2 My great project, first commit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git checkout 55df4c2</span></span></code></pre></div><p>当你以这种方式倒回磁带，如果你按下录音键再次开始，就会丢失以前的工作。Git 默认假定你不想这样做，所以将 HEAD 从项目中分离出来，可以让你如所需的那样工作，而不会因为偶尔的记录而影响之后的工作。</p><p>如果你想看看以前的版本，想要重新做或者尝试不同的方法，那么安全一点的方式就是创建一个新的分支。可以将这个过程想象为尝试同一首歌曲的不同版本，或者创建一个混音的。原始的依然存在，关闭那个分支做你想做的版本吧。</p><p>就像记录到一个空白磁带一样，把你的 Git HEAD 指到一个新的分支处：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout -b remix</span></span>
<span class="line"><span>Switched to a new branch &#39;remix&#39;</span></span></code></pre></div><p>现在你已经切换到了另一个分支，在你面前的是一个替代的干净工作区，准备开始工作吧。</p><p>也可以不用改变时间线来做同样的事情。也许你很想这么做，但切换到一个临时的工作区只是为了尝试一些疯狂的想法。这在工作中完全是可以接受的，请看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>nothing to commit, working directory clean</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git checkout -b crazy_idea</span></span>
<span class="line"><span>Switched to a new branch &#39;crazy_idea&#39;</span></span></code></pre></div><p>现在你有一个干净的工作空间，在这里你可以完成一些奇怪的想法。一旦你完成了，可以保留你的改变，或者丢弃他们，并切换回你的主分支。</p><p>若要放弃你的想法，切换到你的主分支，假装新分支不存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout master</span></span></code></pre></div><p>想要继续使用你的疯狂的想法，需要把它们拉回到主分支，切换到主分支然后合并新分支到主分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout master</span></span>
<span class="line"><span>$ git merge crazy_idea</span></span></code></pre></div><p>git 的分支功能很强大，开发人员在克隆仓库后马上创建一个新分支是很常见的做法；这样，他们所有的工作都在自己的分支上，可以提交并合并到主分支。Git 是很灵活的，所以没有“正确”或“错误”的方式（甚至一个主分支也可以与其所属的远程仓库分离），但分支易于分离任务和提交贡献。不要太激动，你可以如你所愿的有很多的 Git 分支。完全自由。</p><h3 id="远程协作" tabindex="-1">远程协作 <a class="header-anchor" href="#远程协作" aria-label="Permalink to “远程协作”">​</a></h3><p>到目前为止你已经在自己舒适而私密的家中维护着一个 Git 仓库，但如何与其他人协同工作呢？</p><p>有好几种不同的方式来设置 Git 以便让多人可以同时在一个项目上工作，所以首先我们要克隆仓库，你可能已经从某人的 Git 服务器或 GitHub 主页，或在局域网中的共享存储上克隆了一个仓库。</p><p>工作在私人仓库下和共享仓库下唯一不同的是你需要把你的改变 <code>push</code> 到别人的仓库。我们把工作的仓库称之为本地（local）仓库，其他仓库称为远程（remote）仓库。</p><p>当你以读写的方式克隆一个仓库时，克隆的仓库会继承自被称为 origin 的远程库。你可以看看你的克隆仓库的远程仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote --verbose</span></span>
<span class="line"><span>origin  seth@example.com:~/myproject.Git (fetch)</span></span>
<span class="line"><span>origin  seth@example.com:~/myproject.Git (push)</span></span></code></pre></div><p>有一个 origin 远程库非常有用，因为它有异地备份的功能，并允许其他人在该项目上工作。</p><p>如果克隆没有继承 origin 远程库，或者如果你选择以后再添加，可以使用 <code>git remote</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add seth@example.com:~/myproject.Git</span></span></code></pre></div><p>如果你修改了文件，想把它们发到有读写权限的 origin 远程库，使用 <code>git push</code>。第一次推送改变，必须也发送分支信息。不直接在主分支上工作是一个很好的做法，除非你被要求这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout -b seth-dev</span></span>
<span class="line"><span>$ git add exciting-new-file.txt</span></span>
<span class="line"><span>$ git commit -m &#39;first push to remote&#39;</span></span>
<span class="line"><span>$ git push -u origin HEAD</span></span></code></pre></div><p>它会推送你当前的位置（HEAD）及其存在的分支到远程。当推送过一次后，以后每次推送可以不使用 -u 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add another-file.txt</span></span>
<span class="line"><span>$ git commit -m &#39;another push to remote&#39;</span></span>
<span class="line"><span>$ git push origin HEAD</span></span></code></pre></div><h3 id="合并分支" tabindex="-1">合并分支 <a class="header-anchor" href="#合并分支" aria-label="Permalink to “合并分支”">​</a></h3><p>当你工作在一个 Git 仓库时，你可以合并任意测试分支到主分支。当团队协作时，你可能想在将它们合并到主分支之前检查他们的改变：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout contributor</span></span>
<span class="line"><span>$ git pull</span></span>
<span class="line"><span>$ less blah.txt  ### 检查改变的文件</span></span>
<span class="line"><span>$ git checkout master</span></span>
<span class="line"><span>$ git merge contributor</span></span></code></pre></div><p>如果你正在使用 GitHub 或 GitLab 以及类似的东西，这个过程是不同的。但克隆项目并把它作为你自己的仓库都是相似的。你可以在本地工作，将改变提交到你的 GitHub 或 GitLab 帐户，而不用其它人的许可，因为这些库是你自己的。</p><p>如果你想要让你克隆的仓库接受你的改变，需要创建了一个拉取请求（pull request），它使用 Web 服务的后端发送补丁到真正的拥有者，并允许他们审查和拉取你的改变。</p><p>克隆一个项目通常是在 Web 服务端完成的，它和使用 Git 命令来管理项目是类似的，甚至推送的过程也是。然后它返回到 Web 服务打开一个拉取请求，工作就完成了。</p><p>下一部分我们将整合一些有用的插件到 Git 中来帮你轻松的完成日常工作。</p><hr>`,54)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://opensource.com/life/16/7/how-restore-older-file-versions-git"},{default:t(()=>[...s[0]||(s[0]=[i("https://opensource.com/life/16/7/how-restore-older-file-versions-git",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[2]||(s[2]=[i("Seth Kenlon",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),e(a,{href:"https://github.com/strugglingyouth"},{default:t(()=>[...s[3]||(s[3]=[i("strugglingyouth",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const G=p(g,[["render",d]]);export{C as __pageData,G as default};
